-- 쿼리 개수를 센다

@Component
public class QueryCounter {
    private final EntityManagerFactory emf;

    public long count(Runnable work) {
        Statistics s = emf.unwrap(SessionFactory.class).getStatistics();
        s.setStatisticsEnabled(true);
        long before = s.getPrepareStatementCount();
        work.run();
        return s.getPrepareStatementCount() - before;
    }
}

@Test
void 개수_세기() {
    long n = counter.count(() ->
        memberRepository.findAll().forEach(m -> m.getTeam().getName()));
    System.out.println("쿼리 " + n + "개");
}

쿼리 4개

